const DETAILS = {"https://chat.deepseek.com/":{"tagline":"免费、中文友好、代码与推理能力突出的通用助手","tags":["免费","代码","推理","长文档","国内直连"],"intro":["DeepSeek 是深度求索推出的通用 AI 助手，网页版和 App 都能直接用，注册后即可对话，日常使用不收费。","它的强项是代码与逻辑推理：贴一段报错能定位原因，给出可直接运行的改法；面对数学、算法和结构化写作时也更稳。","和多数助手一样支持上传文件、联网搜索和长对话；区别在于中文表达自然、国内网络可直连，不需要额外配置。"],"scenarios":[{"icon":"💻","title":"写代码、改 bug","desc":"把报错和相关代码贴进去，让它定位原因并给出改法，比搜索引擎快一步。"},{"icon":"📄","title":"读长文档","desc":"上传 PDF 或粘贴长文，先要一份摘要，再逐段追问细节。"},{"icon":"🧠","title":"梳理思路","desc":"把模糊需求拆成步骤，或让它扮演反方专门挑毛病。"},{"icon":"✍️","title":"中文写作","desc":"改简历、写周报、润色文案，中文语感比多数海外模型更顺。"}],"steps":["打开 chat.deepseek.com，用手机号或邮箱注册登录","直接在输入框提问；需要推理的题目打开「深度思考」","上传文件（PDF / Word / 图片）让它基于内容回答","需要最新信息时打开联网搜索","要接进自己的程序，去 platform.deepseek.com 申请 API Key"],"links":[{"label":"官网","url":"https://chat.deepseek.com/"},{"label":"开放平台","url":"https://platform.deepseek.com/"}]}}

